import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"معجم المصطلحات","description":"","frontmatter":{},"headers":[],"relativePath":"ar/90-术语词典.md","filePath":"ar/90-术语词典.md","lastUpdated":1789183869000}'),l={name:"ar/90-术语词典.md"};function i(o,t,h,n,s,_){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="معجم-المصطلحات" tabindex="-1">معجم المصطلحات <a class="header-anchor" href="#معجم-المصطلحات" aria-label="Permalink to &quot;معجم المصطلحات&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>90</td></tr><tr><td>الوحدة</td><td>الملاحق والمواد المرجعية</td></tr><tr><td>الكلمات المفتاحية</td><td>معجم المصطلحات، المفاهيم الجوهرية، التعريفات، توحيد المصطلحات، كون هنغ يوان</td></tr></tbody></table><h2 id="أولاً-ملاحظات-حول-المصطلحات" tabindex="-1">أولاً: ملاحظات حول المصطلحات <a class="header-anchor" href="#أولاً-ملاحظات-حول-المصطلحات" aria-label="Permalink to &quot;أولاً: ملاحظات حول المصطلحات&quot;">​</a></h2><p>يجمع هذا المعجم المصطلحات الجوهرية في منظومة العالم الخيالي لحضارة التكافل المرساة، بهدف توحيد استخدام المصطلحات في جميع الوثائق وضمان اتساق التعبير المفاهيمي ودقته. تُرتَّب جميع المصطلحات وفق أول حرف من نطقها الصيني (بينيين)؛ وتحتوي كل مدخلة على اسم المصطلح والاسم المرجعي الإنجليزي (إن وجد) والتعريف وشرحاً موجزاً. هذا المعجم وثيقة تُحدَّث ديناميكياً، ومع توسع منظومة العالم ستُضاف مصطلحات جديدة باستمرار.</p><h2 id="ثانياً-جدول-المصطلحات-الجوهرية" tabindex="-1">ثانياً: جدول المصطلحات الجوهرية <a class="header-anchor" href="#ثانياً-جدول-المصطلحات-الجوهرية" aria-label="Permalink to &quot;ثانياً: جدول المصطلحات الجوهرية&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الرقم</th><th>المصطلح</th><th>التعريف والشرح</th></tr></thead><tbody><tr><td>1</td><td>المرساة</td><td>عقدة مستقرة في شبكة القوانين، تعمل مرجعاً إحداثياً للحفاظ على استقرار قوانين الأبعاد وتحقيق الاتصال عبر الأبعاد والارتداد الزمني. المرساة في جوهرها تكثيف عالي الكثافة لقوانين الكون الأصلانية في موضع مكاني محدد، تملك القدرة على الصيانة الذاتية والمعايرة.</td></tr><tr><td>2</td><td>حضارة التكافل المرساة</td><td>شكل حضاري يقوم على آلية المرساة أساساً تقنياً وعلى التطور التكافلي فكرةً جوهرية. تعارض نظام الزراعة الافتراسية وتدعو إلى إعادة حق اختيار المصير والتطور إلى جميع الكائنات الحية، محققة: عملاً أكثر ربحاً أكثر، ونمواً ذاتياً، وطريقاً لكل فرد، وتقدماً مشتركاً لعشرة آلاف عرق.</td></tr><tr><td>3</td><td>كون هنغ يوان</td><td>اختصار «الكون الأصلاني وانلينغ هنغماو»، وهو المجال الكوني كله الذي تقطن فيه حضارة التكافل المرساة وتديره. كيان مركب يتكون من أربعة مستويات: الأبعاد المادية، وطبقة الطاقة، ومجال الوعي، وشبكة القوانين.</td></tr><tr><td>4</td><td>الكون الأصلاني وانلينغ هنغماو</td><td>الاسم الكامل لكون هنغ يوان. «وانلينغ» (عشرة آلاف روح) يشير إلى جميع أشكال الحياة ذات الإدراك وإمكان التطور؛ و«هنغماو» (مراسي التوازن) يشير إلى آلية المرساة الحافظة لتوازن الكون؛ و«الكون الأصلاني» يؤكد السمتين الجوهريتين: اتخاذ القوانين الأصلانية أساساً والتطور التكافلي اتجاهاً.</td></tr><tr><td>5</td><td>التكافل</td><td>من المفاهيم الجوهرية لحضارة التكافل المرساة، ويشير إلى التطور المشترك للأفراد والأعراق والحضارات المختلفة عبر التعاون المتبادل المنفعة، لا التطور الافتراسي على حساب الآخرين.</td></tr><tr><td>6</td><td>نظام الزراعة الافتراسية</td><td>طريقة زراعة تحقق التطور الذاتي بالتهام طاقة الضعفاء وثروتهم وحتى أصلهم. هو نوع النظام الذي ترفضه حضارة التكافل المرساة رفضاً حاسماً، ويُعتبر الجذر الذي يسرّع زيادة أنتروبيا الكون ويُكثر انقطاعات الحضارات.</td></tr><tr><td>7</td><td>أنظمة الزراعة الأصلانية الثلاثمائة</td><td>مسارات زراعة أصيلة مستخلصة مباشرة من قوانين الكون الأصلانية ومتحقق منها بالمراسي، عددها ثلاثمائة، مقسمة إلى ست فئات كبرى: الاستنتاج الأصلاني، ودورة الحياة، والمبادئ القانونية المكانية، وارتقاء الوعي، والشبكة التكافلية، والهندسة التطبيقية، خمسون نظاماً في كل فئة.</td></tr><tr><td>8</td><td>الأسس الأصلانية الثلاثة</td><td>الأنظمة الأساسية الثلاثة الأولى من بين الأنظمة الثلاثمائة — نظام الاستنتاج التكراري (الأول)، ونظام دورة الحياة (الثاني)، ونظام تسيير المبادئ القانونية المكانية (الثالث) — وهي أساس زراعة جميع الأنظمة الأخرى.</td></tr><tr><td>9</td><td>نظام الاستنتاج التكراري</td><td>نظام الزراعة الأصلاني الأول، الذي يتميز بتضخيم استنتاج الزراعة مئة ضعف، ويستخدم التطبيق التقني لثمرة المضاعفة لرفع قدرة الاستنتاج مئة ضعف، مؤكداً تحسين مسار الزراعة عبر الاستنتاج والتحقق والتكرار.</td></tr><tr><td>10</td><td>نظام دورة الحياة</td><td>نظام الزراعة الأصلاني الثاني، الذي يتمحور حول الدورة الفاضلة لطاقة الحياة، مؤكداً أن تبادل الطاقة بين الزارع والبيئة يجب أن يكون دورياً لا افتراسياً.</td></tr><tr><td>11</td><td>نظام تسيير المبادئ القانونية المكانية</td><td>نظام الزراعة الأصلاني الثالث، الذي يتمحور حول فهم القوانين المكانية وتسيرها، وهو أساس زراعة تطبيقات مهمة مثل التفاعل عبر الأبعاد وبناء الفضاءات المعزولة وتقنية مرآة النسخ.</td></tr><tr><td>12</td><td>ثمرة المضاعفة</td><td>ثمرة المضاعفة المنحدرة من عالم ون بيس، طُبقت تقنياً في كون هنغ يوان، وتستطيع رفع قدرة الزارع على الاستنتاج مئة ضعف، وهي الأداة المساعدة الجوهرية لنظام الاستنتاج التكراري. واحدة من دفعات البداية.</td></tr><tr><td>13</td><td>آلية العقود المرتبطة بالإنتاج</td><td>آلية توزيع الموارد لدى حضارة التكافل المرساة، توزع موارد الزراعة الكونية على الأفراد أو الجماعات بصيغة «عقد»، ويحصل المتعاقدون على حق استخدام الموارد بالعمل والمساهمة، محققين: عملاً أكثر ربحاً أكثر.</td></tr><tr><td>14</td><td>استراتيجية التنشيط بنسبة 20٪</td><td>الهدف الاستراتيجي المرحلي لحضارة التكافل المرساة: تنشيط 20٪ من كائنات الكون في المرحلة الأولى ليصبحوا قوى الأبعاد العليا، واتخاذهم عموداً فقرياً يقود التطور المشترك لـ80٪ المتبقين.</td></tr><tr><td>15</td><td>قوى الأبعاد العليا</td><td>قوي بلغ مستوى عالياً جداً من الزراعة ويستطيع الحفاظ ذاتياً على استقرار قوانين بُعد واحد. هو الهدف التدريبي لاستراتيجية التنشيط بنسبة 20٪، وقوة صيانة مهمة لشبكة المرساة.</td></tr><tr><td>16</td><td>شبكة القوانين</td><td>المستوى الرابع من بنية كون هنغ يوان، والأساس التشغيلي لقوانين الكون الأصلانية والجذر الأساسي للمراسي. تخترق شبكة القوانين الكون كله، وهي الأساس التقني لجميع عمليات القوانين (بما فيها التسير المكاني والارتداد الزمني وتحويل الطاقة).</td></tr><tr><td>17</td><td>البُعد</td><td>منطقة وجود يحددها مجموعة مستقرة نسبياً من القوانين، تملك استمرارية مكانية زمانية مستقلة. لكل بُعد ثوابت فيزيائية وكثافة طاقة وسرعة تدفق زمني ومستوى نشاط وعي فريدة.</td></tr><tr><td>18</td><td>حاجز القوانين</td><td>حاجز قوانين يفصل الأبعاد المتجاورة، وتتوقف قوته على درجة الاختلاف بين متغيرات قوانين الأبعاد المتجاورة. يتطلب العبور بين الأبعاد تجاوز حواجز القوانين.</td></tr><tr><td>19</td><td>بصمة القوانين</td><td>معرّف فريد يولَّد بعملية تجزئة (هاش) على متغيرات القوانين الجوهرية لكل بُعد، طوله 128 بتاً، وهو من المعاملات الجوهرية لمنظومة إحداثيات الأبعاد.</td></tr><tr><td>20</td><td>الملاحظة أولاً ثم التدخل المحدود</td><td>المبدأ التشغيلي الأول للارتداد الزمني وعلم الآثار عبر الأبعاد، ويقتضي أن يكمل أي ارتداد أو علم آثار مرحلة الملاحظة الخالصة أولاً، وألا يُجرى تدخل محدود إلا بعد التأكد من خلوها من المخاطر الكبرى.</td></tr><tr><td>21</td><td>مرآة النسخ</td><td>جهاز نسخ عالي الدقة يقوم على قوانين المبادئ القانونية المكانية، يستطيع إنجاز نسخ كامل 1:1 للمنطقة المستهدفة دون ملامسة الأصل، وهو الجهاز الجوهري لمخطط علم الآثار خارج الموقع.</td></tr><tr><td>22</td><td>الفضاء المعزول</td><td>منطقة قوانين مستقلة تُبنى بتقنية تسيير المبادئ القانونية المكانية، تُستخدم لحمل النسخ الأثرية وكمكان عمل للعاملين في علم الآثار، وتنفصل تماماً عن الكون الخارجي بحواجز القوانين.</td></tr><tr><td>23</td><td>إعادة المعرفة فقط</td><td>المبدأ الجوهري للبروتوكول الأثري، ويعني أن ما يمكن الحصول عليه من الهدف في العملية الأثرية هو المعرفة والمعلومات المجردة فقط، ولا يجوز إعادة أي مواد أو طاقات أو كائنات حية.</td></tr><tr><td>24</td><td>تنقية المعلومات</td><td>العملية التقنية لنزع بصمات قوانين البُعد المصدر المحمولة في المعلومات الخام نزعاً تاماً والإبقاء على المحتوى الدلالي الخالص فقط، وهي الحلقة المفتاحية لضمان أمان المعرفة المُعادة.</td></tr><tr><td>25</td><td>مفارقة الزمن</td><td>الظاهرة التي يصبح فيها المنطق السببي متناقضاً مع نفسه بسبب سلوك تدخلي أثناء عمليات الارتداد الزمني، وتشمل الفئات الأربع الكبرى: مفارقة قتل الجد، والمفارقة المعلوماتية، والمفارقة الوجودية، ومفارقة الأحداث.</td></tr><tr><td>26</td><td>السلسلة السببية</td><td>البنية الخطية المتصلة للأسباب والنتائج بين الأحداث، مفهوم جوهري لقوانين الزمن. الخطر الجوهري لعمليات الارتداد الزمني هو اضطراب السلسلة السببية.</td></tr><tr><td>27</td><td>الدستور التكافلي</td><td>القانون الأساسي لحضارة التكافل المرساة، ذو أعلى قوة قانونية، يرسي اللون الحضاري القائم على مكافحة الافتراس ودعم التكافل، والمبادئ الدستورية الأساسية السبعة.</td></tr><tr><td>28</td><td>مساواة عشرة آلاف عرق</td><td>أحد المبادئ الأساسية السبعة للدستور التكافلي، ويعني أن جميع أشكال الحياة، مهما كان عرقها ومستوى زراعتها وأصلها، متساوية أمام القانون.</td></tr><tr><td>29</td><td>الحياة الشاذة</td><td>أشكال حياة لا تطابق التعريف التقليدي للحياة وتملك أشكال وجود خاصة، وتتطلب التعرف عليها وإدارتها وفق إجراءات المعالجة الموحدة الثلاثية التصنيف.</td></tr><tr><td>30</td><td>الطاقة الشاذة</td><td>أشكال طاقة لا تطابق التصنيف التقليدي للطاقة وتملك خصائص وأنماط سلوك خاصة، وتتطلب تصنيفها وضبطها وفق إجراءات المعالجة الموحدة الثلاثية التصنيف.</td></tr><tr><td>31</td><td>كيان الاستبدال المظلم</td><td>شكل حياة خاص يتصل بمسألة تعايش روحين أخلاقية، ويتطلب إدارته وفق أخلاقيات الروحين وقواعد معالجة الفروع الأربعة.</td></tr><tr><td>32</td><td>أخلاقيات الروحين</td><td>مبادئ أخلاقية لحالة تعايش روحين داخل كيان الاستبدال المظلم، جوهرها احترام حقوق كل من الروحين ومنع الدمج القسري أو إهلاك أحدهما.</td></tr><tr><td>33</td><td>الأنماط الخمسة للحضارة التكافلية</td><td>خمسة أنواع من المجتمعات التكافلية مقسومة وفق خصائص حضارات العالم الواقعي: النمط المكثف لشرق آسيا، والنمط الرعائي للشمال الأوروبي، والنمط التعددي لأمريكا الشمالية، والنمط الاجتماعي لأوروبا القارية، ونمط اللحاق التنموي.</td></tr><tr><td>34</td><td>مسار الارتقاء بأربع مراحل</td><td>المسار الرباعي المراحل للارتقاء الشامل لكون هنغ يوان: البناء على الواقع → التمكين التقني → تطور الوعي → التكافل بين النجوم.</td></tr><tr><td>35</td><td>الواقع أساس</td><td>من المواقف الجوهرية لحضارة التكافل المرساة، ويعني أن العالم الواقعي هو العالم الحقيقي الوحيد، وأن عوالم الروايات تجارب فكرية زائفة، وأن الخيال يُستكمل بالواقع عند نقصه، وما لا يملكه الواقع يُخلق بالارتقاء المبني على القوانين.</td></tr><tr><td>36</td><td>مؤشر التكافل</td><td>مؤشر كمي يقيم درجة اندماج حضارة أو فرد مع الشبكة التكافلية، يغطي أبعاداً متعددة مثل درجة تقاسم الموارد وتكرار التعاون ونسبة السلوك الإيثاري.</td></tr><tr><td>37</td><td>المجلس التشريعي للمرساة</td><td>أعلى هيئة سلطة لحضارة التكافل المرساة، يتكون من ممثلين عن عشرة آلاف عرق بنسب متوازنة، ويمارس السلطة التشريعية وسلطة البت في الأمور الكبرى.</td></tr><tr><td>38</td><td>اللجنة التنفيذية التكافلية</td><td>أعلى هيئة إدارية لحضارة التكافل المرساة، مسؤولة عن تنفيذ الدستور والقوانين والحكم اليومي.</td></tr><tr><td>39</td><td>محكمة التكافل</td><td>أعلى هيئة قضائية لحضارة التكافل المرساة، تمارس السلطة القضائية باستقلال، ومسؤولة عن الرقابة الدستورية والنظر في القضايا الكبرى.</td></tr><tr><td>40</td><td>إدارة الأبعاد</td><td>هيئة متخصصة تابعة للمجلس التشريعي للمرساة، مسؤولة عن صيانة المخزون الرئيسي لإحداثيات الأبعاد والموافقة على تصاريح العبور وإدارة علم الآثار عبر الأبعاد.</td></tr></tbody></table><h2 id="ثالثاً-قواعد-استخدام-المصطلحات" tabindex="-1">ثالثاً: قواعد استخدام المصطلحات <a class="header-anchor" href="#ثالثاً-قواعد-استخدام-المصطلحات" aria-label="Permalink to &quot;ثالثاً: قواعد استخدام المصطلحات&quot;">​</a></h2><ol><li>المصطلحات الواردة في هذا المعجم مصطلحات معيارية، ويجب على جميع الوثائق تفضيل العبارات المعيارية الواردة فيه.</li><li>يجب أن يستخدم المفهوم الواحد المصطلح نفسه في الوثائق المختلفة، ولا يجوز الاستبدال العشوائي بالمرادفات.</li><li>المصطلحات الجديدة الناشئة في العوالم الجديدة يجب تقديمها في حينها إلى لجنة المصطلحات للمراجعة، وإضافتها إلى هذا المعجم بعد الموافقة.</li><li>إذا نُقحت تعريفات المصطلحات، يَعمل بأحدث نسخة من هذا المعجم، ويجب أيضاً تدوين محتوى التنقيح في ملاحظات نسخة الوثيقة.</li><li>عند الاقتباس من مصطلح، يجوز استخدام الاسم الكامل عند أول ورود والاختصار فيما بعد، مع ضمان وضوح المعنى في السياق.</li></ol><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>معجم المصطلحات هو حجر الأساس اللغوي لمنظومة العالم الخيالية بأكملها. يضمن نظام المصطلحات الموحد اتساق المفاهيم بين مئة وثيقة، مما يمكن القراء من التنقل بسلاسة بين الوحدات المختلفة دون غموض في الفهم. ومع ازدياد ثراء المنظومة واكتمالها، سيستمر تحديث هذا المعجم، ويظل دائماً المصدر الموثوق للمصطلحات في جميع الوثائق.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (هنغ يوانتشو: نظرة عامة على الكون)</li><li>02-锚点本源定义与本质 (تعريف وجوهر أصل المرساة)</li><li>99-文档版本与维护说明 (ملاحظات نسخ الوثائق وصيانتها)</li></ul>',12)])])}const u=d(l,[["render",i]]);export{b as __pageData,u as default};
